using System;using System.IO;using System.Reflection;using System.Linq;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class AutoSignatureValidation{
 static AutoSignatureValidation(){EditorApplication.delayCall+=Run;}
 static void Run(){string report="D:/-11-scene3-audit/automatic-signature-validation.txt";if(File.Exists(report))return;if(EditorApplication.isUpdating||EditorApplication.isCompiling){EditorApplication.delayCall+=Run;return;}GameObject host=null;Texture2D decoded=null;try{var image=Resources.Load<Texture2D>("Signature/UNIT001Signature");var data=Resources.Load<TextAsset>("Signature/UNIT001SignatureData");if(!image||!data)throw new Exception("Signature resource missing");decoded=new Texture2D(2,2);if(!decoded.LoadImage(data.bytes))throw new Exception("Saved signature PNG invalid");var px=decoded.GetPixels32();if(!px.Any(p=>p.a>0)||!px.Any(p=>p.a==0))throw new Exception("Expected visible signature over transparent background");host=new GameObject("Temporary automatic signature validation"){hideFlags=HideFlags.HideAndDontSave};var form=host.AddComponent<Scene3SignatureForm>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var type=typeof(Scene3SignatureForm);type.GetField("signature",flags).SetValue(form,image);var confirm=type.GetMethod("Confirm",flags);confirm.Invoke(form,null);if(!(bool)type.GetField("signing",flags).GetValue(form))throw new Exception("Sign & Confirm did not start signing without handwriting");float start=(float)type.GetField("signedAt",flags).GetValue(form);confirm.Invoke(form,null);if(start!=(float)type.GetField("signedAt",flags).GetValue(form))throw new Exception("Repeated confirm restarts signing");if(Scene3SignatureForm.SignerName!="UNIT-001")throw new Exception("Wrong signer name");File.WriteAllText(report,"PASS: exact signer UNIT-001\nPASS: signature image and persistent PNG data load\nPASS: visible signature with transparent background\nPASS: confirm begins automatic signing without manual ink\nPASS: repeated confirm does not restart animation\nUnity compilation passed\nFull play-mode save/return sequence not automatically exercised");}catch(Exception e){File.WriteAllText(report,"FAIL: "+e);}finally{if(host)UnityEngine.Object.DestroyImmediate(host);if(decoded)UnityEngine.Object.DestroyImmediate(decoded);}}
}
